('[질문] N+1 문제가 계속 나는데 원인을 못 찾겠어요 #001', '이영희', '안녕하세요, 이영희입니다. 게시판 목록 화면에 "댓글 1개" 를 함께 보여주려고 하는데 응답이 너무 느립니다.

Post 와 Comment 를 양방향으로 매핑하고 목록에서 post.getComments().size() 를 호출하고 있는데, 로그를 보니 게시글 한 건마다 select 가 하나씩 더 나가더군요. 한 페이지에 20건을 뿌리니 쿼리가 그만큼 늘어납니다.

fetch join, @EntityGraph, @BatchSize 중 어떤 걸 써야 할지 헷갈립니다. 페이징까지 같이 쓰고 있어서 더 조심스러운데 조언 부탁드립니다!', '2026-05-01 09:00:00'),
('[정리] fetch join 과 페이징이 함께 쓰이면 안 되는 이유 #002', '박민수', '박민수입니다. JPA N+1 문제를 정리해 공유합니다.

N+1 은 "부모 N건을 조회한 뒤 각 부모의 연관 데이터를 건드리면 추가 쿼리가 N번 나가는" 현상입니다. 핵심은 부모가 여러 건일 때만 나타난다는 점입니다. 단건 조회는 부모 1건 + 자식 1번이라 총 2쿼리로 끝나고, 이건 N+1 이 아닙니다.

해결책은 크게 세 갈래입니다. (1) join fetch / @EntityGraph 로 한 방에 읽기 — 다만 1:N 컬렉션은 페이징과 상극입니다. (2) @BatchSize 로 IN 절 묶어 읽기 — 페이징이 정상 동작해 실무 표준입니다. (3) 애초에 DTO 로 투영해 필요한 값만 집계하기. 상황 #2 에 맞춰 고르시면 됩니다.', '2026-05-01 10:31:00'),
('[후기] @BatchSize 하나로 장애를 막은 이야기 #003', '최지우', '최지우입니다. 지난 5주간 목록 API 성능 개선 작업을 했고, 그 후기를 남깁니다.

문제는 단순했습니다. 게시글 목록에 댓글 수를 붙이면서 지연 로딩이 그대로 노출됐고, 한 페이지에 50건이니 쿼리가 그만큼 더 나갔습니다. APM 에서 보니 한 요청에 SQL 이 490번 찍히더군요.

@BatchSize 를 100 으로 걸었더니 쿼리 수가 3번으로 떨어졌고 응답 시간도 눈에 띄게 좋아졌습니다. 코드는 거의 손대지 않았는데 효과가 커서, 비슷한 증상 있으시면 먼저 확인해보시길 권합니다.', '2026-05-01 12:02:00'),
('[정보] orphanRemoval 과 cascade 정리 #004', '정해인', '연관관계 설계 기준을 정리했습니다. 작성자: 정해인.

단방향(N:1)만 두면 부모에서 자식 컬렉션을 건드릴 방법이 없어 N+1 이 구조적으로 발생하지 않습니다. 대신 "게시글마다 댓글 수" 같은 요구가 생기면 매번 별도 쿼리를 짜야 하죠. 양방향으로 바꾸면 코드가 편해지는 대신 지연 로딩 폭탄을 스스로 관리해야 합니다.

정리하면, 컬렉션을 정말 자주 쓰는지 먼저 따져보고 필요할 때만 양방향으로 여는 것이 좋습니다. 열었다면 반드시 @BatchSize 나 fetch 전략을 함께 정해두세요(#4).', '2026-05-01 13:33:00'),
('[공지] 서버 점검 안내 #005', '한소희', '[공지] 안녕하세요, 운영자 한소희입니다.

이번 업데이트로 모든 조회 API 응답에 실제 실행된 SQL 목록과 쿼리 개수가 함께 내려갑니다. 화면 우측 리포트 패널에서 전략을 바꿔가며 쿼리 수가 어떻게 변하는지 바로 확인하실 수 있습니다.

