해결책은 크게 세 갈래입니다. (1) join fetch / @EntityGraph 로 한 방에 읽기 — 다만 1:N 컬렉션은 페이징과 상극입니다. (2) @BatchSize 로 IN 절 묶어 읽기 — 페이징이 정상 동작해 실무 표준입니다. (3) 애초에 DTO 로 투영해 필요한 값만 집계하기. 상황 #20 에 맞춰 고르시면 됩니다.', '2026-05-02 13:49:00'),
('[후기] 슬로우 쿼리 로그 켜본 후기 #021', '이영희', '이영희입니다. 지난 3주간 목록 API 성능 개선 작업을 했고, 그 후기를 남깁니다.

문제는 단순했습니다. 게시글 목록에 댓글 수를 붙이면서 지연 로딩이 그대로 노출됐고, 한 페이지에 30건이니 쿼리가 그만큼 더 나갔습니다. APM 에서 보니 한 요청에 SQL 이 490번 찍히더군요.

@BatchSize 를 100 으로 걸었더니 쿼리 수가 3번으로 떨어졌고 응답 시간도 눈에 띄게 좋아졌습니다. 코드는 거의 손대지 않았는데 효과가 커서, 비슷한 증상 있으시면 먼저 확인해보시길 권합니다.', '2026-05-02 15:20:00'),
('[정보] Open Session In View 의 함정 #022', '박민수', '연관관계 설계 기준을 정리했습니다. 작성자: 박민수.

단방향(N:1)만 두면 부모에서 자식 컬렉션을 건드릴 방법이 없어 N+1 이 구조적으로 발생하지 않습니다. 대신 "게시글마다 댓글 수" 같은 요구가 생기면 매번 별도 쿼리를 짜야 하죠. 양방향으로 바꾸면 코드가 편해지는 대신 지연 로딩 폭탄을 스스로 관리해야 합니다.

정리하면, 컬렉션을 정말 자주 쓰는지 먼저 따져보고 필요할 때만 양방향으로 여는 것이 좋습니다. 열었다면 반드시 @BatchSize 나 fetch 전략을 함께 정해두세요(#22).', '2026-05-02 16:51:00'),
