('[정리] DTO 투영 vs 엔티티 조회 비교 #044', '정해인', '정해인입니다. JPA N+1 문제를 정리해 공유합니다.

N+1 은 "부모 N건을 조회한 뒤 각 부모의 연관 데이터를 건드리면 추가 쿼리가 N번 나가는" 현상입니다. 핵심은 부모가 여러 건일 때만 나타난다는 점입니다. 단건 조회는 부모 1건 + 자식 1번이라 총 2쿼리로 끝나고, 이건 N+1 이 아닙니다.

해결책은 크게 세 갈래입니다. (1) join fetch / @EntityGraph 로 한 방에 읽기 — 다만 1:N 컬렉션은 페이징과 상극입니다. (2) @BatchSize 로 IN 절 묶어 읽기 — 페이징이 정상 동작해 실무 표준입니다. (3) 애초에 DTO 로 투영해 필요한 값만 집계하기. 상황 #44 에 맞춰 고르시면 됩니다.', '2026-05-04 02:13:00'),
