('[정리] 영속성 컨텍스트 1차 캐시 정리 #158', '강도현', '강도현입니다. JPA N+1 문제를 정리해 공유합니다.

N+1 은 "부모 N건을 조회한 뒤 각 부모의 연관 데이터를 건드리면 추가 쿼리가 N번 나가는" 현상입니다. 핵심은 부모가 여러 건일 때만 나타난다는 점입니다. 단건 조회는 부모 1건 + 자식 1번이라 총 2쿼리로 끝나고, 이건 N+1 이 아닙니다.

해결책은 크게 세 갈래입니다. (1) join fetch / @EntityGraph 로 한 방에 읽기 — 다만 1:N 컬렉션은 페이징과 상극입니다. (2) @BatchSize 로 IN 절 묶어 읽기 — 페이징이 정상 동작해 실무 표준입니다. (3) 애초에 DTO 로 투영해 필요한 값만 집계하기. 상황 #158 에 맞춰 고르시면 됩니다.', '2026-05-11 07:07:00'),
('[후기] 커넥션 풀 고갈 원인을 찾은 후기 #159', '서지민', '서지민입니다. 지난 5주간 목록 API 성능 개선 작업을 했고, 그 후기를 남깁니다.

문제는 단순했습니다. 게시글 목록에 댓글 수를 붙이면서 지연 로딩이 그대로 노출됐고, 한 페이지에 60건이니 쿼리가 그만큼 더 나갔습니다. APM 에서 보니 한 요청에 SQL 이 880번 찍히더군요.

